package com.smarthire.backend.platform.ai;
import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service public class AiUsageMetricsService { private final AiUsageEventRepository repository; public AiUsageMetricsService(AiUsageEventRepository repository){this.repository=repository;} public void record(String provider,String operation,boolean success,long latencyMs){ AiUsageEvent e=new AiUsageEvent(); e.setProvider(provider); e.setOperation(operation); e.setSuccess(success); e.setLatencyMs(Math.max(0,latencyMs)); repository.save(e);} public long last24Hours(){return repository.countByCreatedAtAfter(LocalDateTime.now().minusHours(24));} public long successfulLast24Hours(){return repository.countByCreatedAtAfterAndSuccessTrue(LocalDateTime.now().minusHours(24));} }
